/* ===========================================================
   ingles4/unit7.js — Inglés 4 · Unit 7: Did you hear…?
   Estructura: sections[] → activities[] → { type, ...datos }
   Tipos disponibles: notes, flashcards, match, mcq, dictation,
   dialog, speaking, stress, reading, fix, soft, comment, order
   Fuente: resúmenes oficiales Evolve Level 4 · Unit 7
   (Grammar / Vocabulary / Functional language summaries)
   =========================================================== */
(() => {
  /* ---------- Vocabulario base ---------- */
  /* Lesson 1 · Describing communication: [palabra, def ES, def EN corta, ejemplo, pregunta] */
  const DC = [
    ['catch up with (someone)', 'ponerse al día con alguien (phr. v.): hablar con alguien que conoces para enterarte de las últimas novedades o comentarlas', 'talk with someone you know in order to learn or discuss the most recent news', 'It was great to catch up with Maxine yesterday. I told her about my new job, and she showed me pictures of her new puppy.', '¿Con qué amigo hace tiempo que no te pones al día?'],
    ['comment (on)', 'comentar (v.): decir o escribir algo que muestra lo que piensas de algo. Se usa con "on": comment ON something', 'say or write something that shows what you think about something', 'I met with my professor to discuss my essay. She commented on what I did well and where I need to improve.', '¿Comentas las publicaciones de tus amigos o solo das "like"?'],
    ['congratulate (on)', 'felicitar (v.): decirle a alguien que te alegras porque hizo algo bueno o le pasó algo bueno. Congratulate someone ON something (nunca "for")', 'tell someone that you are happy because they have done something good or something good has happened to them', 'We arranged a little celebration for Sasha to congratulate her on her promotion.', '¿A quién felicitaste últimamente y por qué?'],
    ['contact', 'contactar, comunicarse con (v.): llamar o enviar un mensaje a alguien. Sin preposición: contact ME (nunca "contact with me")', 'call or send a message to someone', 'You can contact me by phone, text, email, or social media.', '¿Cómo prefieres que te contacten: llamada, WhatsApp o correo?'],
    ['criticize (for)', 'criticar (v.): decir que algo o alguien está mal. Criticize someone FOR something', 'say that something or someone is bad', 'My wife always criticizes me for the way I clean. She thinks I do it wrong.', '¿Por qué te critican en casa? ¿Y tú a quién criticas?'],
    ['explain (to)', 'explicar (v.): aclarar algo dando razones o detalles. Explain something TO someone (nunca "explain me")', 'make something clear or easy to understand by giving reasons for it or details about it', 'I was a little confused about the homework, but the professor explained the lesson very clearly, so I understand it now.', '¿Qué cosa de tu trabajo te cuesta explicar a tu familia?'],
    ['gossip (about)', 'chismear, cotillear (v.): hablar de la vida privada de otras personas', "talk about other people's private lives", "John and Brian always gossip about people at the office. I think it's rude. They should stop focusing on everyone's private lives and get back to work.", '¿Se chismea mucho en tu oficina?'],
    ['inform (someone) of', 'informar de (phr. v.): dar a alguien información sobre algo. Siempre con objeto: inform ME OF something', 'give someone information about something', 'I had a meeting with my manager this morning. She informed me of some changes that are being made to the company structure.', '¿De qué te informó tu jefe la última vez que te llamó a una reunión?'],
    ['keep in touch with', 'mantenerse en contacto con (v. phrase): seguir comunicándote con alguien por teléfono, correo, mensajes, etc.', 'continue to communicate with someone by phone, email, text, etc.', 'I like using video chat to keep in touch with my brother. We try to talk every week.', '¿Con qué amigo del colegio todavía te mantienes en contacto?'],
    ['mention', 'mencionar (v.): hablar o escribir brevemente de algo o alguien. Mention something / that… (no lleva "me" obligatorio)', 'briefly speak or write about something or someone', "I ran into Katherine today, and she mentioned that you're neighbors. I didn't know you moved!", '¿Qué mencionó tu jefe en la última reunión que te llamó la atención?'],
    ['persuade (to)', 'persuadir, convencer (v.): hacer que alguien haga o piense algo dándole buenas razones. Persuade someone TO do something', 'make someone do or think something by giving them good reasons', "The salesperson tried to persuade us to get the latest Toyota model. She said it's very reliable and has all the features we're looking for.", '¿Quién te convenció de comprar algo que no necesitabas?'],
    ['reply to', 'responder a, contestar (phr. v.): reply TO someone / TO a message (nunca "reply her")', 'answer', "A: Did Sarah text you? B: Yes, she wants to know where we are. I'll reply to her and tell her we're at your place.", '¿Cuánto tardas en responder a un mensaje de WhatsApp?'],
    ['report (on)', 'informar, reportar (v.): describir un hecho o una situación reciente, sobre todo en televisión, radio o prensa', 'describe a recent event or situation, especially on television, the radio, or in a newspaper', "We're live in Seoul, reporting on an unusual event that happened this morning.", '¿Qué noticia reportaron hoy en tu newsfeed?'],
    ['respond to', 'responder a, reaccionar a (phr. v.): decir o hacer algo como respuesta o reacción a lo que alguien dijo o hizo', 'say or do something as an answer or reaction to something that has been said or done', "We need to respond to Jane and John's wedding invitation to tell them we're coming.", '¿Respondes a todas las invitaciones o algunas las dejas pasar?'],
  ];
  /* Lesson 2 · Communicating online */
  const CO = [
    ['clickbait', 'cebo de clics, "clickbait" (n.): artículos, fotos, etc. de internet que buscan llamar la atención para que hagas clic en un enlace', 'articles or photos on the internet that try to attract attention and encourage people to click on links', "A: Oh, this looks interesting. A new study shows that chocolate helps you lose weight! B: Oh, don't read that. It's just clickbait.", '¿Cuál fue el último titular "clickbait" en el que caíste?'],
    ['geo-tag', 'geoetiqueta (n.): dato electrónico que muestra dónde está alguien o algo; se puede añadir a una foto o a un comentario en redes', 'a piece of electronic data that shows where someone or something is, attached to a photo or comment', 'Are you posting that photo? You should add a geo-tag for the restaurant so people know where we are.', '¿Pones geoetiqueta en tus fotos o prefieres no mostrar dónde estás?'],
    ['hashtag', 'hashtag, etiqueta (n.): el símbolo # usado en redes sociales para describir el tema general de una publicación', 'the symbol # used on social media for describing the general subject of a post', 'Rob and Evelyn started a hashtag for their wedding. Guests can post their photos online and use the hashtag #RandEGetMarried so other people can easily find the photos.', '¿Qué hashtag usarías para La Consentida?'],
    ['lifecaster', '"lifecaster" (n.): persona que publica todo sobre sí misma en las redes sociales', 'someone who puts everything about themselves on social media', 'My friend Carla is a lifecaster. She posts on social media all day long about everything she does and especially everything she eats!', '¿Conoces a algún "lifecaster"? ¿Qué es lo que más publica?'],
    ['lurker', 'mirón, usuario pasivo (n.): alguien que lee las publicaciones o mensajes en redes sin participar', 'someone who reads the posts or messages on social media without taking part', "I'm a lurker on a message board about video games. I read everything, but I never post.", '¿Eres "lurker" o "lifecaster"? ¿En qué red?'],
    ['meme', 'meme (n.): idea, imagen, video, etc. que se difunde muy rápido por internet', 'an idea, image, video, etc. that is spread very quickly on the internet', "All of my friends keep sharing this meme of a cat dressed like a businessperson. People add their own funny captions. It's pretty funny!", '¿Cuál es el último meme que te hizo reír?'],
    ['newsfeed', 'muro, feed de noticias (n.): página o pantalla que se actualiza a menudo para mostrar las últimas noticias o información', 'a web page or screen that updates often to show the latest news or information', 'My newsfeed has been very active today. My friends keep posting updates about their plans and their recent vacations.', '¿Qué aparece más en tu newsfeed: noticias, amigos o publicidad?'],
    ['podcaster', 'podcaster (n.): persona que produce programas de audio para descargar o escuchar en línea', 'a person who produces audio programs to download or listen to online', 'My friend Frank is a podcaster. He records a podcast every week where he talks about new movies and video games.', '¿Qué podcaster escuchas? ¿Sobre qué habla?'],
    ['profile', 'perfil (n.): descripción de ti mismo y de tus intereses en una web o una app de redes sociales', 'a description of yourself and your interests on a website or social networking app', "Before you accept a friend request, look at the person's profile: the photo, the city, the job and the interests. If the profile is empty, it's probably a fake account.", '¿Qué dice tu perfil de LinkedIn sobre ti?'],
    ['status update', 'actualización de estado (n.): información que publicas en línea contando lo que haces o piensas en un momento concreto', 'information that you post online telling people what you are doing or thinking at a particular time', "This restaurant is great. I'm going to post a status update about it so other people can know about it.", '¿Cuándo fue la última vez que publicaste una actualización de estado?'],
    ['tag', 'etiquetar (v.): añadir un enlace al perfil de alguien desde una foto o un comentario en redes', "add a link to someone's profile from a photo or comment on social media", 'A: Oh, I love that photo! Are you going to post it? B: Yeah. Do you want me to tag you in it? Then it will show up on your profile, too.', '¿Te molesta que te etiqueten en fotos sin preguntarte?'],
    ['timeline', 'biografía, línea de tiempo (n.): la parte de una red social que muestra lo que has añadido tú o lo que tiene que ver contigo', 'the part of a social media website that shows items that have been added by you or that relate to you', "Don't tag me in that photo. I don't want it to show up on my timeline.", '¿Qué fue lo último que apareció en tu timeline?'],
    ['trending topic', 'tema del momento, tendencia (n.): historia o noticia que se ha vuelto popular en redes sociales', 'a story or news item that has become popular on social media', 'The subject of pollution from plastic straws was a trending topic on social media recently. Many people were demanding that businesses stop using them.', '¿Cuál es el trending topic de hoy en Perú?'],
  ];
  const ALL = [...DC, ...CO];
  const findW = k => ALL.find(x => x[0] === k);

  /* situación → expresión: [frase con hueco, respuesta, clave en DC/CO, respuestas que NO sirven como distractor] */
  const SIT = [
    ["I hadn't seen Rosa in two years, so we went for coffee to ___ each other.", 'catch up with', 'catch up with (someone)', ['keep in touch with']],
    ['My manager read my report and ___ my conclusions. She said they were clear.', 'commented on', 'comment (on)', []],
    ['Everyone called Sasha to ___ her on her new job.', 'congratulate', 'congratulate (on)', []],
    ['If you have any questions, you can ___ me by email.', 'contact', 'contact', ['reply to']],
    ['My brother ___ everything I cook. According to him, nothing has enough salt.', 'criticizes', 'criticize (for)', ['comments on']],
    ["I didn't understand the new system, so Luis ___ it to me step by step.", 'explained', 'explain (to)', []],
    ["Those two spend the whole day talking about other people's private lives. They love to ___.", 'gossip', 'gossip (about)', []],
    ['HR sent an email to ___ us ___ the new vacation policy.', 'inform … of', 'inform (someone) of', []],
    ['We live in different countries now, but we ___ each other by video chat.', 'keep in touch with', 'keep in touch with', ['catch up with']],
    ["Ana ___ that you were moving to Chile. Is that true?", 'mentioned', 'mention', ['reported']],
    ['The salesman tried to ___ me to buy the more expensive phone.', 'persuade', 'persuade (to)', []],
    ["Sarah texted me an hour ago and I still haven't ___ her.", 'replied to', 'reply to', ['responded to']],
    ['The journalist is in Cusco ___ the floods for the evening news.', 'reporting on', 'report (on)', []],
    ["We need to ___ the invitation by Friday to tell them if we're coming.", 'respond to', 'respond to', ['reply to']],
    ['"Doctors hate this simple trick!" Don\'t click on that, it\'s just ___.', 'clickbait', 'clickbait', []],
    ['Add a ___ to the photo so people know which beach this is.', 'geo-tag', 'geo-tag', []],
    ['Use the ___ #LaConsentidaPE so we can find all the photos of the event.', 'hashtag', 'hashtag', []],
    ['Carla posts what she eats, where she is and how she feels, every hour. She\'s a real ___.', 'lifecaster', 'lifecaster', []],
    ['I read everything on that forum, but I never post anything. I\'m a ___.', 'lurker', 'lurker', []],
    ['That picture of the cat in a suit is everywhere! It\'s the ___ of the week.', 'meme', 'meme', []],
    ['I opened the app and my ___ was full of vacation photos.', 'newsfeed', 'newsfeed', ['timeline']],
    ['Frank records an audio program every week about movies. He\'s a ___.', 'podcaster', 'podcaster', []],
    ['Before you accept the request, check the person\'s ___: photo, city, interests.', 'profile', 'profile', []],
    ['She posted a ___: "Finally on vacation! Two weeks without email."', 'status update', 'status update', []],
    ['Can you ___ me in that photo? I want it to show up on my profile.', 'tag', 'tag', []],
    ['Don\'t post that picture, I don\'t want it on my ___ for everyone to see.', 'timeline', 'timeline', ['newsfeed']],
    ['The new tax law is a ___ today; thousands of people are posting about it.', 'trending topic', 'trending topic', []],
  ];
  const SITW = SIT.map(s => s[1]);

  window.UNIT_DATA['ingles4/unit7'] = {
    source: 'Evolve · Unit 7 · Did you hear…?',
    description: 'Contar lo que otros dijeron y preguntaron: reported statements (say / tell / explain / inform, cambio de tiempo verbal), reported questions (orden de afirmación, sin do/does/did, if), verbos de comunicación, vocabulario de redes sociales y cómo recontar chismes, noticias e historias sin perder el hilo.',
    cando: [
      "Contar lo que alguien dijo con reported speech y el cambio de tiempos correcto (<i>She said she was tired</i>)",
      "Reportar preguntas sin <i>do / does / did</i> y con <i>if</i> para las de sí o no",
      "Usar <i>say / explain / mention</i> sin objeto y <i>tell / inform / persuade</i> con objeto",
      "Hablar de comunicación online: <i>clickbait, hashtag, lurker, status update, trending topic, newsfeed</i>",
      "Contar una noticia o conversación: <i>Apparently…</i> · <i>Turns out…</i> · <i>You'll never believe what…</i>, y retomar el hilo con <i>As I was saying…</i>",
    ],
    map: [
      ['Vocabulary', '14 verbos y expresiones para describir la comunicación (<i>catch up with, comment on, congratulate on, contact, criticize for, explain to, gossip, inform of, keep in touch with, mention, persuade to, reply to, report on, respond to</i>) y 13 palabras de comunicación en línea (<i>clickbait, geo-tag, hashtag, lifecaster, lurker, meme, newsfeed, podcaster, profile, status update, tag, timeline, trending topic</i>)', 'Flashcards con audio, verbo ↔ definición, palabra ↔ definición, situación → expresión y la preposición correcta (<i>congratulate ON, reply TO, contact Ø</i>)'],
      ['Grammar', '<b>Reported statements</b>: <i>said / told me / explained / informed me</i> + cambio de tiempo (presente → pasado, pasado → past perfect), sin cambio para hechos, hábitos y futuro; instrucciones con <i>told / persuaded + objeto + to</i>. <b>Reported questions</b>: orden de afirmación, sin <i>do / does / did</i>, <i>if</i> para preguntas de sí/no, sin signo de interrogación', 'Elige el tiempo, ¿say o tell?, preguntas indirectas, corrige los errores típicos del hispanohablante, ordena, reescribe directo → indirecto, repaso de las Units 1-6'],
      ['Listening', 'Historias de bodas perdidas, postales encontradas y entrevistas; chismes de oficina', 'Dictado con voz sintética y dos diálogos nuevos (chisme en la cafetería y lo que preguntó la gerente nueva) con preguntas'],
      ['Speaking', 'Contar una conversación, recontar una noticia, explicar un meme o un trending topic, reportar lo que te preguntaron', 'Retos con cronómetro y reconocimiento de voz; entonación de <i>You\'ll NEVER believe…</i>, <i>Well, turns OUT…</i>, las comillas irónicas y la sílaba tónica de <i>conGRAtulate, CRIticize, perSUADE</i>'],
      ['Reading', 'Comunicación en línea: cómo compartimos y leemos noticias', 'Texto nuevo sobre <i>lurkers</i>, <i>lifecasters</i> y <i>clickbait</i> + inferir significado'],
      ['Writing', 'Recontar una conversación o una noticia; publicar en redes', 'Corrige errores típicos (<i>she said me, asked me where did I live, told that, explain me, reply her</i>), escribe el recuento de una conversación en estilo indirecto y una publicación con hashtag, etiqueta y geoetiqueta, con checklist'],
      ['Social English', '<i>You\'ll never believe what… · Apparently… · Someone told me that… · Well, turns out,… · What happened was,… · He was like,… · The funny thing was,… · In the end… · As I was saying… · Where was I? Oh yeah,… · I lost my train of thought!</i> · comillas irónicas · <i>I\'m like</i>', 'Ordenar diálogos, retomar el hilo, respuesta rápida'],
    ],

    sections: [
      { id: 'home', label: 'Inicio', render: 'overview', activities: [] },

      /* ================= VOCABULARY ================= */
      { id: 'vocab', label: 'Vocabulary', activities: [
        { label: 'Flashcards', type: 'flashcards', eyebrow: 'Flashcards con audio', title: 'Toca la tarjeta para girarla', intro: 'Anverso: la palabra o expresión (con su preposición cuando la lleva). Reverso: significado, ejemplo del curso y una pregunta para ti. Pulsa 🔊 para oír la pronunciación.',
          cards: [
            ...DC.map(t => ({ cat: 'Describing communication', w: t[0], def: t[1], ex: t[3], ask: t[4] })),
            ...CO.map(t => ({ cat: 'Communicating online', w: t[0], def: t[1], ex: t[3], ask: t[4] })),
          ] },
        { label: 'Verbo ↔ Definición', type: 'match', eyebrow: 'Describing communication', title: 'Empareja el verbo con su definición', intro: 'Toca un verbo de la izquierda y luego su definición (en inglés, como en el curso) a la derecha. Fíjate en los matices: mention es breve, explain da detalles, report es periodístico, gossip es sobre la vida privada.',
          pairs: DC.map(t => [t[0].replace(/ \((on|to|for|about|someone\) of|someone)\)/, '').replace('inform (someone) of', 'inform of'), t[2]]), round: 6 },
        { label: 'Online ↔ Definición', type: 'match', eyebrow: 'Communicating online', title: 'Empareja la palabra con su definición', intro: 'Vocabulario de redes sociales. Ojo con los parecidos: newsfeed (lo que publican los demás) vs timeline (lo que tiene que ver contigo), lurker (solo lee) vs lifecaster (publica todo).',
          pairs: CO.map(t => [t[0], t[2]]), round: 6 },
        { label: '¿Qué expresión es?', type: 'mcq', eyebrow: 'En contexto', title: 'Lee la situación y elige la expresión', intro: 'Comunicación cara a cara y en línea mezcladas. Fíjate en las pistas de la frase (¿es una noticia?, ¿es privado?, ¿es un símbolo?, ¿quién publica y quién solo lee?).', pool: 8,
          build: ({ pick, esc }) => pick(SIT, 8).map(s => { const t = findW(s[2]); const bad = SITW.filter(x => x !== s[1] && !s[3].includes(x)); return { q: esc(s[0]).replace(/___/g, '<span class="blank">?</span>'), opts: [s[1], ...pick(bad, 3)], a: s[1], why: `<b>${t[0]}</b> — ${t[1]}. “${t[3]}”` }; }) },
        { label: 'La preposición correcta', type: 'mcq', eyebrow: 'Verb + preposition', title: 'Elige la preposición (o ninguna)', intro: 'Aquí caen muchos hispanohablantes: <i>congratulate <b>on</b></i> (no <s>for</s>), <i>reply / respond <b>to</b></i>, <i>contact <b>Ø</b></i> (no <s>with</s>), <i>explain something <b>to</b> someone</i>, <i>inform someone <b>of</b></i>, <i>criticize someone <b>for</b></i>, <i>comment <b>on</b></i>, <i>gossip <b>about</b></i>, <i>tag someone <b>in</b> a photo</i>.', pool: 8, items: [
          { blank: 1, q: 'We called Sasha to congratulate her ___ her promotion.', opts: ['on', 'for', 'by', 'about'], a: 'on', why: '<b>congratulate someone ON something</b>. "Felicitar por" no se traduce con <i>for</i>.' },
          { blank: 1, q: 'Sarah texted me, so I need to reply ___ her.', opts: ['to', '—', 'at', 'with'], a: 'to', why: '<b>reply TO</b> someone / a message. <s>reply her</s> es un error muy común.' },
          { blank: 1, q: 'You can contact ___ me by phone or email.', opts: ['—', 'with', 'to', 'at'], a: '—', why: '<b>contact</b> no lleva preposición: <i>contact me</i>. Calco del español "contactar con".' },
          { blank: 1, q: 'The professor explained the lesson ___ us very clearly.', opts: ['to', '—', 'for', 'at'], a: 'to', why: '<b>explain something TO someone</b>. Nunca <s>explain us the lesson</s>.' },
          { blank: 1, q: 'My manager informed me ___ some changes in the team.', opts: ['of', 'about of', 'that', 'for'], a: 'of', why: '<b>inform someone OF something</b> (también <i>inform someone that…</i>, pero no <s>inform of that</s>).' },
          { blank: 1, q: 'My wife criticizes me ___ the way I clean the kitchen.', opts: ['for', 'by', 'about', 'of'], a: 'for', why: '<b>criticize someone FOR something</b>: la razón de la crítica.' },
          { blank: 1, q: 'She commented ___ my essay and said the introduction was too long.', opts: ['on', 'about', 'to', '—'], a: 'on', why: '<b>comment ON something</b>.' },
          { blank: 1, q: 'They spend the whole lunch gossiping ___ people from the office.', opts: ['about', 'of', 'on', 'for'], a: 'about', why: '<b>gossip ABOUT someone</b>.' },
          { blank: 1, q: 'We have to respond ___ the invitation before Friday.', opts: ['to', '—', 'at', 'with'], a: 'to', why: '<b>respond TO</b> something. Igual que <i>reply to</i>.' },
          { blank: 1, q: 'The reporter is in Arequipa reporting ___ the volcano.', opts: ['on', 'about of', 'of', 'for'], a: 'on', why: '<b>report ON</b> an event: cubrir una noticia.' },
          { blank: 1, q: 'Do you want me to tag you ___ this photo?', opts: ['in', 'on', 'at', 'to'], a: 'in', why: '<b>tag someone IN a photo</b>. Frase del curso.' },
          { blank: 1, q: "I don't want that picture to show up ___ my timeline.", opts: ['on', 'in', 'at', 'to'], a: 'on', why: '<i>show up <b>on</b> my timeline / on my profile</i>.' },
          { blank: 1, q: 'I try to keep in touch ___ my cousins in Chile.', opts: ['with', 'to', 'of', '—'], a: 'with', why: '<b>keep in touch WITH someone</b>.' },
          { blank: 1, q: 'The salesperson persuaded us ___ the new model.', opts: ['to get', 'get', 'getting', 'for get'], a: 'to get', why: '<b>persuade someone TO do</b> something: infinitivo con <i>to</i>.' },
          { blank: 1, q: 'It was great to catch up ___ Maxine yesterday.', opts: ['with', 'to', 'on', '—'], a: 'with', why: '<b>catch up WITH someone</b> (ponerse al día). <i>Catch up <b>on</b></i> es ponerse al día con cosas: <i>catch up on the news</i>.' },
          { blank: 1, q: 'She mentioned ___ you were moving to Chile.', opts: ['that', 'me that', 'to that', 'about'], a: 'that', why: '<b>mention that…</b> sin objeto. Si quieres decir a quién: <i>mentioned <b>to me</b> that…</i>' },
        ] },
      ] },

      /* ================= GRAMMAR ================= */
      { id: 'grammar', label: 'Grammar', activities: [
        { label: 'Notas', type: 'notes', eyebrow: 'Reported statements · Reported questions', title: 'Contar lo que otros dijeron y preguntaron', html: `
          <h3>1 · Reported statements: el verbo "retrocede" un paso</h3>
          <p style="margin:8px 0 14px">Cuando cuentas lo que alguien dijo, normalmente lo haces <b>después</b>, así que el verbo que reportas pasa a un tiempo más pasado (<i>backshift</i>). El verbo introductor va en pasado: <b>said, told me, explained, mentioned, informed me, commented, reported</b>. <i>That</i> es opcional.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Dijo (directo)</th><th>Reportas (indirecto)</th><th>Ejemplo del curso</th></tr></thead><tbody>
            <tr><td><b>Presente simple</b><br>"The app <b>allows</b> me to contact my family."</td><td><b>Pasado simple</b></td><td>One new arrival explained that the app <b>allowed</b> him to contact his family.</td></tr>
            <tr><td><b>Presente continuo</b><br>"I<b>'m working</b> from home."</td><td><b>Pasado continuo</b></td><td>She said she <b>was working</b> from home.</td></tr>
            <tr><td><b>has to / can / will</b><br>"It <b>has to</b> be a mistake."</td><td><b>had to / could / would</b></td><td>My husband said that it <b>had to</b> be a mistake.</td></tr>
            <tr><td><b>Pasado simple</b><br>"Chris <b>contacted</b> me."</td><td><b>Past perfect</b> (had + participio)</td><td>Brian called and told us that Chris <b>had contacted</b> him.</td></tr>
            <tr><td><b>Present perfect</b><br>"I<b>'ve seen</b> your post."</td><td><b>Past perfect</b></td><td>He told Carly that he <b>had seen</b> her post and <b>had recognized</b> the postcard immediately.</td></tr>
          </tbody></table></div>
          <div class="hint" style="margin-top:14px"><b>También cambian</b> los pronombres y las referencias de tiempo y lugar: <i>I → he/she</i>, <i>my → his/her</i>, <i>you → me</i>, <i>here → there</i>, <i>today → that day</i>, <i>tomorrow → the next day</i>, <i>yesterday → the day before</i>, <i>this → that</i>. "I'll call <b>you tomorrow</b>" → He said he would call <b>me the next day</b>.</div>

          <h3 style="margin-top:22px">2 · Cuándo NO hace falta cambiar el tiempo</h3>
          <p style="margin:8px 0 14px">Si lo que reportas es un <b>hecho</b>, un <b>hábito</b> que sigue siendo verdad, o un <b>evento futuro</b> que todavía no ha pasado, puedes dejar el tiempo original.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Caso</th><th>Directo</th><th>Indirecto (sin cambio)</th></tr></thead><tbody>
            <tr><td><b>Hecho</b></td><td>"Lima <b>is</b> the capital of Peru."</td><td>The guide said that Lima <b>is</b> the capital of Peru.</td></tr>
            <tr><td><b>Hábito actual</b></td><td>"What sports <b>do</b> you <b>play</b> on the weekend?"</td><td>She asked me what sport I <b>play</b> on the weekend.</td></tr>
            <tr><td><b>Futuro aún pendiente</b></td><td>"We<b>'re arriving</b> tomorrow at 10 p.m."</td><td>She informed me that they<b>'re arriving</b> / they<b>'re going to arrive</b> / they<b>'ll arrive</b> tomorrow at 10 p.m.</td></tr>
          </tbody></table></div>

          <h3 style="margin-top:22px">3 · Verbos introductores: ¿con objeto o sin objeto?</h3>
          <div class="scroll-x"><table class="table"><thead><tr><th>Grupo</th><th>Verbos</th><th>Patrón</th><th>Ejemplo</th></tr></thead><tbody>
            <tr><td><b>Necesitan objeto</b> (a quién)</td><td><b>tell, inform</b></td><td>tell <b>me / him / Carly</b> (that)… · inform <b>me of</b> / <b>me that</b>…</td><td>He <b>told Carly</b> that he had seen her post. · She <b>informed me of</b> some changes.</td></tr>
            <tr><td><b>No llevan objeto</b></td><td><b>say, explain, report, comment, mention</b></td><td>say (that)… · explain (that)… / explain it <b>to</b> me · mention (that)…</td><td>My husband <b>said that</b> it had to be a mistake. · She <b>mentioned that</b> you're neighbors.</td></tr>
          </tbody></table></div>
          <div class="hint small" style="margin-top:12px"><s>She said me that…</s> → <b>She told me that…</b> / <b>She said that…</b> · <s>He told that…</s> → <b>He told us that…</b> · <s>She explained me…</s> → <b>She explained (to me) that…</b> · <s>They informed that…</s> → <b>They informed us that…</b></div>

          <h3 style="margin-top:22px">4 · Reported instructions & suggestions: verbo + objeto + to-infinitivo</h3>
          <p style="margin:8px 0 14px">Para reportar órdenes, peticiones, consejos o persuasión: <b>told / asked / persuaded / reminded / advised</b> + <b>quién</b> + <b>to</b> + verbo. En negativo: <b>not to</b>.</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Directo</th><th>Indirecto</th></tr></thead><tbody>
            <tr><td>"Bring him over to our house."</td><td>We <b>told Brian to bring</b> him over to our house.</td></tr>
            <tr><td>"You should write something about it."</td><td>Carly <b>persuaded the newspaper to write</b> something about it.</td></tr>
            <tr><td>"Can you send me the report?"</td><td>My boss <b>asked me to send</b> her the report.</td></tr>
            <tr><td>"Don't tag me in that photo."</td><td>She <b>told me not to tag</b> her in that photo.</td></tr>
          </tbody></table></div>

          <h3 style="margin-top:22px">5 · Reported questions: ya no es una pregunta</h3>
          <p style="margin:8px 0 14px">Reportar una pregunta la convierte en una <b>afirmación sobre una pregunta</b>. Por eso: (1) <b>orden de afirmación</b> (sujeto + verbo), (2) <b>sin do / does / did</b>, (3) <b>sin signo de interrogación</b>, (4) el tiempo retrocede igual que en las afirmaciones, (5) preguntas de <b>sí/no</b> → <b>if</b> (o <i>whether</i>).</p>
          <div class="scroll-x"><table class="table"><thead><tr><th>Pregunta directa</th><th>Pregunta reportada</th><th>Fíjate</th></tr></thead><tbody>
            <tr><td>"Who <b>is she</b>?"</td><td>I asked him who <b>she was</b>.</td><td>sujeto antes del verbo</td></tr>
            <tr><td>"What <b>do you do</b> for a living?"</td><td>He asked me what <b>I did</b> for a living.</td><td>desaparece <i>do</i>; <i>do</i> (hacer) → <i>did</i></td></tr>
            <tr><td>"How long <b>do you plan</b> to stay in town?"</td><td>I asked her how long <b>she planned</b> to stay in town.</td><td>sin <i>do</i>, verbo en pasado</td></tr>
            <tr><td>"<b>Have you had</b> a lot of attention from fans?"</td><td>I asked her <b>if she'd had</b> a lot of attention from fans.</td><td>sí/no → <b>if</b>; present perfect → past perfect</td></tr>
            <tr><td>"<b>Do you want</b> to go with us?"</td><td>She asked me <b>if I wanted</b> to go with them.</td><td><i>us → them</i></td></tr>
            <tr><td>"<b>Do you like</b> our city?"</td><td>I asked her <b>if she liked</b> our city.</td><td>punto final, no <b>?</b></td></tr>
          </tbody></table></div>
          <div class="hint small" style="margin-top:12px"><b>Trampas típicas:</b> <s>He asked me where did I live</s> → <b>where I lived</b> · <s>She asked if do you like it</s> → <b>if you liked it</b> · <s>I asked her what time was it</s> → <b>what time it was</b> · <s>He asked me that if I was ready</s> → <b>if I was ready</b> (nunca <i>that</i> + <i>if</i>) · <s>She asked me where I lived?</s> → termina en <b>punto</b>. Otros introductores: <i>wanted to know, wondered</i>.</div>` },
        { label: 'Elige el tiempo', type: 'mcq', eyebrow: 'Reported statements · backshift', title: 'Completa la frase reportada', intro: 'Lee lo que dijo la persona (entre comillas) y elige la forma correcta en estilo indirecto. Recuerda: presente → pasado, pasado y present perfect → past perfect, will → would, can → could. Y fíjate en los pronombres.', pool: 8, items: [
          { blank: 1, q: '"I live in Surco." → She said she ___ in Surco.', opts: ['lived', 'lives', 'had lived', 'was lived'], a: 'lived', why: 'Presente simple → <b>pasado simple</b>: <i>lived</i>.' },
          { blank: 1, q: '"I\'m working from home today." → He told me he ___ from home that day.', opts: ['was working', 'is working', 'had worked', 'worked'], a: 'was working', why: 'Presente continuo → <b>pasado continuo</b>. Y <i>today → that day</i>.' },
          { blank: 1, q: '"We\'ve finished the project." → They said they ___ the project.', opts: ['had finished', 'have finished', 'were finished', 'finish'], a: 'had finished', why: 'Present perfect → <b>past perfect</b>: <i>had finished</i>.' },
          { blank: 1, q: '"I saw your post." → He told Carly that he ___ her post.', opts: ['had seen', 'has seen', 'seen', 'was seeing'], a: 'had seen', why: 'Pasado simple → <b>past perfect</b>. Frase del curso: <i>he had seen her post</i>.' },
          { blank: 1, q: '"It has to be a mistake." → My husband said that it ___ a mistake.', opts: ['had to be', 'has to be', 'must to be', 'have to be'], a: 'had to be', why: '<i>has to</i> → <b>had to</b>. Frase del curso.' },
          { blank: 1, q: '"I can\'t come to the party." → She said she ___ come to the party.', opts: ["couldn't", "can't", "couldn't to", "didn't can"], a: "couldn't", why: '<i>can</i> → <b>could</b>; <i>can\'t</i> → <b>couldn\'t</b>.' },
          { blank: 1, q: '"I\'ll call you tomorrow." (te lo dijo la semana pasada) → He said he ___ call me the next day.', opts: ['would', 'will', 'would to', 'is going to'], a: 'would', why: 'La llamada ya pasó, así que <i>will</i> → <b>would</b> y <i>tomorrow → the next day</i>.' },
          { blank: 1, q: '"We\'re arriving tomorrow at 10 p.m." (te lo dice hoy; todavía no llegan) → She informed me that they ___ tomorrow at 10 p.m.', opts: ['are arriving', 'arrived', 'had arrived', 'had been arriving'], a: 'are arriving', why: 'Evento <b>futuro aún pendiente</b>: no hace falta cambiar el tiempo. Frase del curso.' },
          { blank: 1, q: '"Water boils at 100 degrees." → The teacher explained that water ___ at 100 degrees.', opts: ['boils', 'had boiled', 'was boiling', 'is boiling'], a: 'boils', why: 'Es un <b>hecho</b>: se puede dejar el presente.' },
          { blank: 1, q: '"I go to the gym every morning." (y lo sigue haciendo) → She mentioned that she ___ to the gym every morning.', opts: ['goes', 'had gone', 'was going', 'is go'], a: 'goes', why: '<b>Hábito</b> que sigue siendo verdad: no hace falta el cambio.' },
          { blank: 1, q: '"I didn\'t send the email." → He explained that he ___ the email.', opts: ["hadn't sent", "didn't sent", "hasn't sent", "hadn't send"], a: "hadn't sent", why: 'Pasado negativo → <b>hadn\'t + participio</b>.' },
          { blank: 1, q: '"The app allows me to contact my family." → One new arrival explained that the app ___ him to contact his family.', opts: ['allowed', 'had allowed', 'allow', 'was allow'], a: 'allowed', why: 'Presente → <b>pasado simple</b>. Frase del curso. (<i>had allowed</i> sería para un pasado original.)' },
          { blank: 1, q: '"I\'m going to buy a new phone." → She said she ___ a new phone.', opts: ['was going to buy', 'is going to buy', 'would going to buy', 'went to buy'], a: 'was going to buy', why: '<i>am/is going to</i> → <b>was going to</b>.' },
          { blank: 1, q: '"Chris contacted me." → Brian told us that Chris ___ him.', opts: ['had contacted', 'has contacted', 'contact', 'was contact'], a: 'had contacted', why: 'Pasado → <b>past perfect</b>. Frase del curso.' },
          { blank: 1, q: '"I must finish this today." → He said he ___ finish it that day.', opts: ['had to', 'must to', 'musted', 'has to'], a: 'had to', why: '<i>must</i> → <b>had to</b> (o se deja <i>must</i>). Nunca <s>must to</s>.' },
          { blank: 1, q: '"I love your photos." → Ana told me she loved ___ photos.', opts: ['my', 'your', 'her', 'their'], a: 'my', why: 'Ana me habla a mí: <i>your</i> (mis fotos) → <b>my</b>.' },
          { blank: 1, q: '"We\'ll meet here at six." → They said they would meet ___ at six.', opts: ['there', 'here', 'in here', 'this place'], a: 'there', why: '<i>here → <b>there</b></i> cuando ya no estás en ese lugar.' },
          { blank: 1, q: '"You look tired." → She told me I ___ tired.', opts: ['looked', 'had looked', 'was look', 'looking'], a: 'looked', why: 'Presente → <b>pasado</b>. <i>You → I</i> porque me lo dijo a mí.' },
        ] },
        { label: '¿Say, tell o…?', type: 'mcq', eyebrow: 'Reporting verbs · con objeto / sin objeto', title: 'Elige el verbo introductor correcto', intro: '<b>tell</b> e <b>inform</b> necesitan decir a quién (<i>told me, informed us</i>). <b>say, explain, report, comment, mention</b> no llevan objeto directo de persona (<i>said that, explained that, explained it <b>to</b> me</i>). Para instrucciones: <i>told / asked / persuaded + persona + <b>to</b> + verbo</i>.', pool: 8, items: [
          { blank: 1, q: 'She ___ that she was going to be late.', opts: ['said', 'told', 'informed', 'said me'], a: 'said', why: 'Sin objeto → <b>said that</b>. <i>told</i> e <i>informed</i> exigen persona.' },
          { blank: 1, q: 'She ___ me that she was going to be late.', opts: ['told', 'said', 'explained', 'mentioned'], a: 'told', why: 'Con objeto (<i>me</i>) → <b>told me</b>. <s>said me</s> no existe.' },
          { blank: 1, q: 'The manager ___ us of the changes in the schedule.', opts: ['informed', 'said', 'told', 'explained'], a: 'informed', why: '<b>informed us OF</b> something. <i>told us about</i> también sería correcto, pero no con <i>of</i>.' },
          { blank: 1, q: 'He ___ the problem to me very clearly.', opts: ['explained', 'told', 'informed', 'said me'], a: 'explained', why: '<b>explain something TO someone</b>.' },
          { blank: 1, q: 'I ran into Katherine and she ___ that you\'re neighbors.', opts: ['mentioned', 'told', 'informed', 'said me'], a: 'mentioned', why: '<b>mentioned that…</b> sin objeto. Frase del curso.' },
          { blank: 1, q: 'The journalist ___ that the bridge had been closed.', opts: ['reported', 'told', 'informed', 'said to'], a: 'reported', why: '<b>reported that…</b> (describir una noticia). <i>told / informed</i> necesitarían persona.' },
          { blank: 1, q: 'My professor ___ on what I did well in the essay.', opts: ['commented', 'told', 'said', 'informed'], a: 'commented', why: '<b>comment ON</b> something.' },
          { blank: 1, q: 'Nobody ___ me about the meeting!', opts: ['told', 'said', 'explained', 'mentioned'], a: 'told', why: '<b>tell someone about</b> something. <s>said me</s>, <s>explained me</s>, <s>mentioned me</s> no funcionan.' },
          { blank: 1, q: 'He said ___ he had seen the post.', opts: ['that', 'me that', 'to that', 'me'], a: 'that', why: '<b>say (that)…</b> Si quieres añadir a quién: <i>he said <b>to me</b> that…</i>, pero nunca <s>said me</s>.' },
          { blank: 1, q: 'She told ___ the office was closed.', opts: ['us that', 'that', 'to us that', 'us to that'], a: 'us that', why: '<b>tell + persona + (that)</b>.' },
          { blank: 1, q: 'They informed the residents ___ the new rules.', opts: ['of', 'that of', 'to', 'for'], a: 'of', why: '<b>inform someone OF something</b>.' },
          { blank: 1, q: 'Can you explain ___ how the app works?', opts: ['to me', 'me', 'for me', 'at me'], a: 'to me', why: '<b>explain TO me</b>. <s>Explain me</s> es el calco más típico del español.' },
          { blank: 1, q: 'Ana persuaded ___ the new restaurant.', opts: ['me to try', 'me try', 'to me try', 'me trying'], a: 'me to try', why: '<b>persuade + persona + TO + verbo</b>.' },
          { blank: 1, q: 'We told Brian ___ him over to our house.', opts: ['to bring', 'bring', 'that bring', 'bringing'], a: 'to bring', why: 'Instrucción reportada: <b>told Brian TO bring</b>. Frase del curso.' },
          { blank: 1, q: 'Carly persuaded the newspaper ___ something about it.', opts: ['to write', 'write', 'writing', 'for write'], a: 'to write', why: '<b>persuaded + objeto + to-infinitivo</b>. Frase del curso.' },
          { blank: 1, q: 'My boss asked ___ the report by Friday.', opts: ['me to send', 'me send', 'to me send', 'me sending'], a: 'me to send', why: 'Petición reportada: <b>asked me TO send</b>.' },
          { blank: 1, q: 'She told me ___ her in that photo.', opts: ['not to tag', 'to not tagging', 'don\'t tag', 'that not tag'], a: 'not to tag', why: 'Instrucción negativa: <b>told me NOT TO + verbo</b>.' },
        ] },
        { label: 'Preguntas reportadas', type: 'mcq', eyebrow: 'Reported questions', title: 'Convierte la pregunta en una afirmación sobre la pregunta', intro: 'Orden de afirmación (sujeto + verbo), sin <i>do / does / did</i>, <b>if</b> para las preguntas de sí/no, el tiempo retrocede y la frase termina en punto.', pool: 8, items: [
          { blank: 1, q: '"Where do you live?" → He asked me where ___.', opts: ['I lived', 'did I live', 'do I live', 'lived I'], a: 'I lived', why: 'Sin <i>do</i>, orden <b>sujeto + verbo</b>, presente → pasado.' },
          { blank: 1, q: '"Who is she?" → I asked him who ___.', opts: ['she was', 'was she', 'is she', 'was her'], a: 'she was', why: '<b>who she was</b>: sujeto antes del verbo. Frase del curso.' },
          { blank: 1, q: '"What do you do for a living?" → He asked me what I ___ for a living.', opts: ['did', 'does', 'had done', 'was do'], a: 'did', why: 'El <i>do</i> auxiliar desaparece; el <i>do</i> de "hacer" pasa a <b>did</b>. Frase del curso.' },
          { blank: 1, q: '"How long do you plan to stay?" → I asked her how long she ___ to stay in town.', opts: ['planned', 'plans', 'did plan', 'was plan'], a: 'planned', why: 'Presente → <b>pasado</b>, sin auxiliar.' },
          { blank: 1, q: '"Do you want to go with us?" → She asked me ___ I wanted to go with them.', opts: ['if', 'that', 'do', 'what'], a: 'if', why: 'Pregunta de sí/no → <b>if</b> (o <i>whether</i>). Nunca <i>that</i>.' },
          { blank: 1, q: '"Do you like our city?" → I asked her if she ___ our city.', opts: ['liked', 'did like', 'like', 'was like'], a: 'liked', why: 'Sin <i>did</i>; el verbo principal va en <b>pasado</b>. Frase del curso.' },
          { blank: 1, q: '"Have you had a lot of attention from fans?" → I asked her if she ___ a lot of attention from fans.', opts: ['had had', 'has had', 'has have', 'did have'], a: 'had had', why: 'Present perfect → <b>past perfect</b>: <i>if she\'d had</i>. Sí, dos <i>had</i> seguidos.' },
          { blank: 1, q: '"Are you coming to the party?" → He asked me ___ to the party.', opts: ['if I was coming', 'if was I coming', 'that I was coming', 'if I am come'], a: 'if I was coming', why: '<b>if + sujeto + verbo</b>: <i>if I was coming</i>.' },
          { blank: 1, q: '"Can you help me?" → She asked ___ her.', opts: ['if I could help', 'if could I help', 'that I could help', 'if I can to help'], a: 'if I could help', why: '<i>can</i> → <b>could</b>, orden de afirmación.' },
          { blank: 1, q: '"Why did you leave early?" → My boss asked me why I ___ early.', opts: ['had left', 'did leave', 'did I leave', 'have left'], a: 'had left', why: 'Pasado → <b>past perfect</b>, y desaparece <i>did</i>.' },
          { blank: 1, q: '"What time does the meeting start?" → She asked what time the meeting ___.', opts: ['started', 'did start', 'does start', 'start'], a: 'started', why: 'Sin <i>does</i>; presente → <b>pasado</b>.' },
          { blank: 1, q: '"Where were you yesterday?" → He asked me where I ___ the day before.', opts: ['had been', 'was been', 'were', 'did be'], a: 'had been', why: 'Pasado → <b>past perfect</b>; <i>yesterday → the day before</i>.' },
          { blank: 1, q: '"Will you be at the office tomorrow?" → She asked me if I ___ at the office the next day.', opts: ['would be', 'will be', 'would been', 'am'], a: 'would be', why: '<i>will</i> → <b>would</b>.' },
          { q: 'Elige la frase correcta.', opts: ['He asked me where I worked.', 'He asked me where did I work.', 'He asked me where I work?', 'He asked me that where I worked.'], a: 'He asked me where I worked.', why: 'Sin <i>did</i>, sin <i>that</i>, sin signo de interrogación.' },
          { q: 'Elige la frase correcta.', opts: ['She asked me if I liked the city.', 'She asked me do I like the city.', 'She asked me if do I like the city.', 'She asked me that if I liked the city.'], a: 'She asked me if I liked the city.', why: '<b>if + sujeto + verbo en pasado</b>. Ni <i>do</i> ni <i>that</i>.' },
          { q: 'Elige la frase correcta.', opts: ['I asked her what time it was.', 'I asked her what time was it.', 'I asked her what time is it?', 'I asked her what time did it was.'], a: 'I asked her what time it was.', why: '<i>what time <b>it was</b></i>: sujeto antes del verbo.' },
          { blank: 1, q: '"How much did it cost?" → He wanted to know how much it ___.', opts: ['had cost', 'did it cost', 'costed', 'did cost'], a: 'had cost', why: '<i>wanted to know</i> funciona como <i>asked</i>. Pasado → <b>past perfect</b>; <i>cost</i> es irregular.' },
          { blank: 1, q: 'I asked her where she was from___ (elige el signo final)', opts: ['.', '?', '!', ','], a: '.', why: 'Una pregunta reportada es una <b>afirmación</b>: termina en <b>punto</b>.' },
        ] },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · errores típicos del hispanohablante', title: 'Reescribe la frase corrigiendo el error', intro: 'Los errores más frecuentes al reportar: <i>said me</i>, <i>told that</i>, <i>asked me where did I</i>, <i>if do you</i>, olvidar el cambio de tiempo, <i>explain me</i>, <i>reply her</i>. Corrígelos y compara con la solución.', items: [
          { bad: 'She said me that she was tired.', good: 'She told me that she was tired.', why: '<b>say</b> no lleva persona: <i>she said that…</i> Si dices a quién, usa <b>tell</b>: <i>she told me that…</i>' },
          { bad: 'He asked me where did I live.', good: 'He asked me where I lived.', why: 'Pregunta reportada = orden de afirmación y <b>sin did</b>: <i>where I lived</i>.' },
          { bad: 'My boss told to me that the office was closed.', good: 'My boss told me that the office was closed.', why: '<b>tell someone</b> sin <i>to</i>: <i>told me</i>. (<i>said to me</i> sí lleva <i>to</i>.)' },
          { bad: 'She asked if do you like the food.', good: 'She asked if you liked the food.', why: 'Después de <b>if</b>, nada de <i>do / does / did</i>; el verbo pasa a <b>pasado</b>.' },
          { bad: 'Yesterday he said that he is sick.', good: 'Yesterday he said that he was sick.', why: 'Lo dijo ayer → el presente retrocede: <i>is</i> → <b>was</b>.' },
          { bad: 'She told me that she has seen my post.', good: 'She told me that she had seen my post.', why: 'Present perfect → <b>past perfect</b>: <i>had seen</i>.' },
          { bad: 'Ana explained me the problem.', good: 'Ana explained the problem to me.', why: '<b>explain something TO someone</b>. Nunca <s>explain me</s>.' },
          { bad: 'I asked her what time was it.', good: 'I asked her what time it was.', why: 'Sujeto antes del verbo: <i>what time <b>it was</b></i>.' },
          { bad: 'He asked me if I can help him?', good: 'He asked me if I could help him.', why: 'Dos errores: <i>can</i> → <b>could</b> y la frase termina en <b>punto</b>, no en interrogación.' },
          { bad: 'They informed us the changes.', good: 'They informed us of the changes.', why: '<b>inform someone OF something</b>.' },
          { bad: 'My mom persuaded me buy a new phone.', good: 'My mom persuaded me to buy a new phone.', why: '<b>persuade + persona + TO + verbo</b>.' },
          { bad: 'I will reply her message tonight.', good: 'I will reply to her message tonight.', why: '<b>reply TO</b> a message / someone.' },
          { bad: 'Please contact with me by email.', good: 'Please contact me by email.', why: '<b>contact</b> no lleva preposición. Calco de "contactar con".' },
          { bad: 'She congratulated me for my promotion.', good: 'She congratulated me on my promotion.', why: '<b>congratulate someone ON something</b>.' },
          { bad: 'The manager told that the meeting was cancelled.', good: 'The manager said that the meeting was cancelled.', why: '<b>tell</b> exige persona (<i>told us that</i>). Sin persona, usa <b>say</b>.' },
          { bad: 'He asked me that if I was ready.', good: 'He asked me if I was ready.', why: 'Nunca <i>that</i> + <i>if</i>. Solo <b>asked me if</b>.' },
        ] },
        { label: 'Ordena: directo → indirecto', type: 'order', eyebrow: 'Ordena el diálogo', title: 'Primero la conversación real, luego cómo se la cuentan a otra persona', intro: 'Cada diálogo tiene dos partes: la conversación original y, después, cómo uno de ellos se la cuenta a un tercero en estilo indirecto. Toca las líneas en el orden correcto.', dialogs: [
          ['Marta: Hi Luis! Long time no see. Where do you work now?', 'Luis: I work at a bank in San Isidro. I build their payments app.', 'Marta: Do you like it?', "Luis: I love it, but I'm working too many hours this month.", 'Ana (later): So, did you catch up with Luis?', 'Marta: Yes! I asked him where he worked, and he told me he worked at a bank in San Isidro.', 'Ana: And does he like it?', 'Marta: He said he loved it, but he was working too many hours that month.'],
          ['Diego: Have you seen the photos from the wedding?', "Paula: No, I haven't. Can you tag me in them?", "Diego: Sure. Don't look at the one of me dancing, though.", 'Carla (next day): What did Diego say about the photos?', "Paula: He asked me if I had seen them, and I asked him to tag me.", 'Carla: Anything else?', 'Paula: He told me not to look at the one of him dancing!'],
          ['Manager: How long have you worked here, Rosa?', "Rosa: Six years. I started in 2020.", 'Manager: Can you send me the documentation by Friday?', "Rosa: Of course, I'll email it to you tomorrow.", 'Luis (that evening): How was the meeting with the new manager?', 'Rosa: Fine. She asked me how long I had worked there, and I told her I had started in 2020.', 'Luis: Did she ask you for anything?', 'Rosa: She asked me to send her the documentation by Friday, and I said I would email it the next day.'],
        ] },
        { label: 'Reescribe: afirmaciones', type: 'soft', eyebrow: 'Direct → reported statements · escritura', title: 'Pasa la frase a estilo indirecto', explain: 'Escribe la frase reportada completa: <b>verbo introductor en pasado</b> (<i>said / told me / explained / informed us</i>) + el verbo <b>un paso atrás</b> (presente → pasado, pasado → past perfect, will → would, can → could) + cambio de pronombres. Sin comillas.', missing: 'Falta algo: un verbo introductor en pasado (<i>said / told me / explained / informed us / mentioned</i>), el cambio de tiempo (<i>was, had, would, could, -ed</i>) o has dejado comillas', pattern: /^(?![\s\S]*["“”])(?![\s\S]*\bsaid (me|him|her|us|them)\b)(?![\s\S]*\b(told|informed) (that|me that that)\b)(?![\s\S]*\bexplained (me|him|her|us|them)\b)[\s\S]*\b(said|told [a-z]+|explained|mentioned|informed [a-z]+ (that|of)|commented|reported)\b[\s\S]*\b(was|were|had|would|could|might|didn['’]t|wasn['’]t|weren['’]t|hadn['’]t|wouldn['’]t|couldn['’]t|went|knew|got|made|took|came|saw|thought|found|left|felt|kept|met|sent|spent|bought|gave|ran|lost|won|wrote|ate|slept|broke|forgot|began|[a-z]+ed)\b/, items: [
          { h: 'Ana: "I live in Lima." → Ana said…', a: 'Ana said that she lived in Lima.' },
          { h: 'Luis (a ti): "I\'m looking for a new job." → Luis told me…', a: 'Luis told me that he was looking for a new job.' },
          { h: 'My team (a la gerente): "We have finished the project." → My team told the manager…', a: 'My team told the manager that they had finished the project.' },
          { h: 'Carla (a ti): "I saw your post yesterday." → Carla told me…', a: 'Carla told me that she had seen my post the day before.' },
          { h: 'The technician: "The app doesn\'t work on old phones." → The technician explained…', a: "The technician explained that the app didn't work on old phones." },
          { h: 'Pedro: "I\'ll reply to the email tonight." → Pedro said…', a: 'Pedro said that he would reply to the email that night.' },
          { h: 'The manager (a todos): "There are some changes in the schedule." → The manager informed us…', a: 'The manager informed us that there were some changes in the schedule.' },
          { h: 'My wife: "I can\'t find my keys." → My wife said…', a: "My wife said that she couldn't find her keys." },
        ] },
        { label: 'Reescribe: preguntas', type: 'soft', eyebrow: 'Direct → reported questions · escritura', title: 'Pasa la pregunta a estilo indirecto', explain: 'Escribe la pregunta reportada completa: <b>asked me / asked her / wanted to know</b> + <b>palabra interrogativa</b> o <b>if</b> + <b>sujeto + verbo</b> (un paso atrás). Sin <i>do / does / did</i>, sin invertir el orden y <b>sin signo de interrogación</b>.', missing: 'Revisa: empieza con <i>asked (me/him/her) + if / what / where…</i>, el verbo va DESPUÉS del sujeto (nada de <i>did I, was she, are you</i>) y la frase termina en punto, no en "?"', pattern: /^(?![\s\S]*\?)(?![\s\S]*\b(do|does|did|are|is|am|was|were|can|could|will|would|have|has|had) (i|you|he|she|we|they|it)\b)(?![\s\S]*\bthat (if|whether|what|where|when|why|who|which|how)\b)[\s\S]*\b(asked|wanted to know|wondered)\b( (me|him|her|us|them|[a-z]+))?\s+(if|whether|what|where|when|why|who|which|how)\b/, items: [
          { h: 'Marta (a ti): "Where do you work?" → Marta asked me…', a: 'Marta asked me where I worked.' },
          { h: 'A tourist (a ti): "Do you like Lima?" → A tourist asked me…', a: 'A tourist asked me if I liked Lima.' },
          { h: 'My boss: "What time does the meeting start?" → My boss asked…', a: 'My boss asked what time the meeting started.' },
          { h: 'Diego (a ti): "Have you seen the new meme?" → Diego asked me…', a: 'Diego asked me if I had seen the new meme.' },
          { h: 'My colleague (a ti): "Can you send me the report?" → My colleague asked me…', a: 'My colleague asked me if I could send her the report.' },
          { h: 'The teacher (a Luis): "Why are you late?" → The teacher asked Luis…', a: 'The teacher asked Luis why he was late.' },
          { h: 'My neighbor (a ti): "How long have you lived here?" → My neighbor asked me…', a: 'My neighbor asked me how long I had lived there.' },
          { h: 'Ana (a ti): "Will you be at the office tomorrow?" → Ana asked me…', a: 'Ana asked me if I would be at the office the next day.' },
        ] },
        { label: 'Repaso Units 1-6', type: 'mcq', eyebrow: 'Repaso espaciado', title: 'Units 1-6 con vocabulario de la Unit 7', intro: 'Present perfect, condicionales reales, <i>too / enough</i>, especulación con modales, oraciones de relativo, past perfect, <i>was supposed to</i> y pasiva.', items: [
          { blank: 1, q: 'I ___ in touch with my cousin since she moved to Chile.', opts: ['have kept', 'keep', 'am keeping', 'kept'], a: 'have kept', why: '<i>since</i> + momento del pasado hasta hoy → present perfect (Unit 1).' },
          { blank: 1, q: 'If that article ___ clickbait, I won\'t click on it.', opts: ['is', 'will be', 'would be', 'were'], a: 'is', why: 'Condicional real: <i>if</i> + presente → <i>will</i> (Unit 2).' },
          { blank: 1, q: 'That status update is ___ long; nobody is going to read it.', opts: ['too', 'enough', 'very much', 'so many'], a: 'too', why: '<b>too</b> + adjetivo = demasiado (Unit 3).' },
          { blank: 1, q: 'She posts every ten minutes. She ___ be a lifecaster.', opts: ['must', 'can', 'might not', "can't"], a: 'must', why: 'Deducción segura → <b>must</b>; nunca <i>can</i> para especular (Unit 4).' },
          { blank: 1, q: 'The podcaster ___ show I listen to every week lives in Arequipa.', opts: ['whose', 'who', 'which', 'where'], a: 'whose', why: 'Posesión (su programa) → <b>whose</b> (Unit 4).' },
          { blank: 1, q: 'By the time I replied to the message, she ___ already left.', opts: ['had', 'has', 'was', 'did'], a: 'had', why: '<i>By the time</i> + acción anterior → past perfect (Unit 5).' },
          { blank: 1, q: 'We ___ to meet for coffee, but she had to work late.', opts: ['were supposed', 'supposed', 'were suppose', 'are supposed'], a: 'were supposed', why: 'Plan fallido: <b>was/were supposed to</b> + <i>but</i> (Unit 5).' },
          { blank: 1, q: 'The photos ___ by hundreds of people in one hour.', opts: ['were shared', 'shared', 'was shared', 'were share'], a: 'were shared', why: 'Pasiva de pasado, plural → <b>were shared</b> (Unit 6).' },
        ] },
      ] },

      /* ================= LISTENING ================= */
      { id: 'listen', label: 'Listening', activities: [
        { label: 'Dictado', type: 'dictation', eyebrow: 'Dictation', title: 'Escucha y escribe exactamente lo que oyes', intro: 'Usa la voz del navegador. Repite las veces que quieras y baja la velocidad si hace falta. Ojo con <i>had</i> (suena "d" pegada: <i>he\'d seen</i>), con <i>would</i> y con las contracciones (<i>you\'ll, turns out, didn\'t</i>).',
          sentences: ["You'll never believe what happened to me this morning.", 'Apparently, he had all the information on his phone.', 'Someone told me that he accidentally overslept.', 'She asked me what I did for a living.', 'He told Carly that he had seen her post.', 'Well, turns out, the article was just clickbait.', 'I asked her if she had had a lot of attention from fans.', "She informed me that they're arriving tomorrow at ten.", 'Where was I? Oh yeah, in the end, they found the postcard.', "Don't tag me in that photo. I don't want it on my timeline.", 'It was great to catch up with Maxine yesterday.', 'The funny thing was, nobody had read the message.'] },
        { label: 'Diálogo 1 · Chisme', type: 'dialog', eyebrow: 'Listening for gossip and news', title: 'Escucha el diálogo y responde', intro: 'Paula y Diego se ponen al día en la cafetería de la oficina. Fíjate en cómo empieza la historia, en el estilo indirecto y en la palabra que Diego dice con "comillas".',
          lines: [['Paula', "You'll never believe what happened at Marco's wedding on Saturday."], ['Diego', 'What? I saw the photos on my newsfeed. Everyone was tagged except David.'], ['Paula', 'Exactly! Well, turns out, David missed the whole thing. Apparently, he lost his phone and all the information was in there.'], ['Diego', "That's not what I heard. Someone told me that he \"accidentally\" overslept."], ['Paula', "Ha! Anyway, I caught up with Marco yesterday and he told me he wasn't angry. He said that David had called him to apologize."], ['Diego', 'And what did David say?'], ['Paula', 'He explained that his alarm hadn\'t gone off. Marco was like, "Sure, and your phone disappeared too?"'], ['Diego', "Poor David. Did Marco ask him why he hadn't texted anyone?"], ['Paula', "He did, and David said he didn't remember anybody's number. Where was I? Oh yeah, in the end, Marco persuaded him to post a public apology with the wedding hashtag."], ['Diego', 'The funny thing is, that apology is now a trending topic in the office.']],
          questions: [
            { q: 'How does Paula start the story?', opts: ["You'll never believe what…", 'As I was saying…', 'I lost my train of thought!'], a: "You'll never believe what…", why: 'Frase para <b>empezar</b> a contar una historia sorprendente.' },
            { q: 'Why does Diego say "accidentally" with a special intonation?', opts: ["He doesn't really believe David overslept by accident", 'He thinks David had an accident', 'He is sure David lost his phone'], a: "He doesn't really believe David overslept by accident", why: 'Insider English: entonación (o comillas al escribir) para decir que <b>no te lo crees</b>.' },
            { q: 'What did David explain to Marco?', opts: ["That his alarm hadn't gone off", 'That he had lost his phone', 'That he had been at another wedding'], a: "That his alarm hadn't gone off", why: '"He explained that his alarm hadn\'t gone off." Lo del teléfono es lo que dice la gente, no David.' },
            { q: 'What did Marco persuade David to do?', opts: ['To post a public apology with the wedding hashtag', 'To buy a new phone', 'To delete his profile'], a: 'To post a public apology with the wedding hashtag', why: '"Marco persuaded him <b>to post</b> a public apology": persuade + objeto + to-infinitivo.' },
            { q: 'Which phrase does Paula use to get back on track?', opts: ['Where was I? Oh yeah…', 'What happened was…', 'In the end…'], a: 'Where was I? Oh yeah…', why: 'Se había desviado y retoma el hilo con <b>Where was I? Oh yeah,…</b>' },
          ] },
        { label: 'Diálogo 2 · La gerente nueva', type: 'dialog', eyebrow: 'Listening for reported questions', title: 'Escucha el diálogo y responde', intro: 'Rosa le cuenta a Luis todo lo que la gerente nueva le preguntó en la reunión. Escúchalo entero: casi todo está en preguntas reportadas.',
          lines: [['Luis', 'Hey Rosa, how was the meeting with the new manager?'], ['Rosa', 'Interesting. She asked me a lot of questions. First she asked me how long I had worked at the bank.'], ['Luis', 'And what did you say?'], ['Rosa', 'I told her I had been there for six years. Then she asked me if I was happy with my team and what I did on a typical day.'], ['Luis', 'Did she mention the new project?'], ['Rosa', 'Yes. She informed us of some changes in the schedule and asked whether we could start in November.'], ['Luis', 'Did she ask about me?'], ['Rosa', 'Actually, yes. She asked me who you were and if you were the person who had built the payments app. I said you were.'], ['Luis', 'Wow. What else?'], ['Rosa', 'She asked me to send her the documentation by Friday. Oh, and she told me to tell you to contact her this week.'], ['Luis', "OK, I'll reply to her email tonight."]],
          questions: [
            { q: 'What was the first question the manager asked Rosa?', opts: ['How long have you worked at the bank?', 'Are you happy with your team?', 'Can we start in November?'], a: 'How long have you worked at the bank?', why: '"She asked me how long I had worked at the bank" = "How long <b>have you worked</b>…?" (present perfect → past perfect).' },
            { q: 'Which direct question did the manager ask about the project?', opts: ['Can you start in November?', 'Did you start in November?', 'Will you start in November?'], a: 'Can you start in November?', why: '"asked whether we <b>could</b> start" ← "<b>Can</b> you start…?" <i>Whether</i> = <i>if</i>.' },
            { q: 'What did the manager want to know about Luis?', opts: ['Who he was and if he had built the payments app', 'If he wanted a new job', 'How long he had worked there'], a: 'Who he was and if he had built the payments app', why: '"She asked me who you were and if you were the person who had built the payments app."' },
            { q: 'What instruction did Rosa receive for Luis?', opts: ['To tell him to contact the manager this week', 'To send him the documentation', 'To ask him to start in November'], a: 'To tell him to contact the manager this week', why: '"She told me to tell you to contact her this week": instrucción reportada con <i>told + objeto + to</i>.' },
          ] },
      ] },

      /* ================= SPEAKING ================= */
      { id: 'speak', label: 'Speaking', activities: [
        { label: 'Retos', type: 'speaking', eyebrow: 'Speaking challenge', challenges: [
          { t: 'Catching up: a conversation I had', task: 'Cuenta una conversación real que tuviste esta semana (con un colega, un amigo, un cliente). Usa estilo indirecto: she said that…, he told me that…, she explained that…, he mentioned that…. Al menos cinco frases reportadas con el cambio de tiempo.', model: "Yesterday I caught up with my friend Renzo, who I hadn't seen in months. He told me that he had changed jobs in August and that he was working for a fintech now. He said the salary was better, but he was working longer hours. He mentioned that his team was looking for a Java developer, and he asked me if I was happy at the bank. I explained that I was comfortable, but that I wanted to learn new things. In the end, he persuaded me to send him my CV, just to see. He also told me not to mention it to anyone at work yet!", tags: ['told me', 'said', 'explained', 'mentioned', 'asked me if', 'had', 'was', 'persuaded me to'] },
          { t: 'News from my newsfeed', task: 'Recuenta una noticia o historia que viste en tu newsfeed esta semana. Empieza con You\'ll never believe what… o I heard that…, usa Apparently…, Well, turns out…, In the end…, y reporta lo que dijo alguien (the article said that…, the mayor explained that…).', model: "You'll never believe what I read on my newsfeed this morning. Apparently, a man in Trujillo found a wallet from 1998 inside an old sofa he had bought online. The article said that the wallet had a student ID, three photos and a lottery ticket. He posted a status update asking for help, and it became a trending topic in a few hours. Well, turns out, the owner was living in Spain, and her cousin recognized her in the photo. The owner told the newspaper that she had lost the wallet on her first day at university. The funny thing was, the lottery ticket was a winner – for ten soles. In the end, they met by video call and she asked him to keep the ticket.", tags: ["you'll never believe", 'apparently', 'turns out', 'the article said', 'told the newspaper', 'in the end', 'the funny thing was', 'trending topic'] },
          { t: 'Explain a meme or a trending topic', task: 'Explica a alguien que no usa redes sociales qué es un meme o un trending topic que viste hoy: qué muestra, por qué es gracioso o importante, quién lo comparte, qué hashtag lleva. Usa al menos seis palabras de Communicating online.', model: "There's a meme going around this week that I have to explain to my mom. It's a photo of a very serious cat sitting in front of a laptop, and people add captions like 'Me reviewing my own code on Monday.' It started on a developers' forum, and now it's all over my newsfeed with the hashtag #MondayCat. Most people just share it, but the lifecasters in my timeline post their own versions every day. I'm usually a lurker – I read everything and never post – but I tagged two colleagues in it because it describes our code reviews perfectly. For a couple of hours it was even a trending topic in Peru, which says a lot about how we feel about Mondays.", tags: ['meme', 'caption', 'newsfeed', 'hashtag', 'lifecaster', 'timeline', 'lurker', 'tagged', 'trending topic'] },
          { t: 'What my colleague asked me', task: 'Un colega nuevo (o un entrevistador, o un cliente) te hizo muchas preguntas. Repórtalas: he asked me where…, she wanted to know if…, he asked me how long…. Al menos seis preguntas reportadas, sin do/does/did y en orden de afirmación.', model: "A new developer joined my team on Monday and he asked me a hundred questions. First he asked me how long I had worked at the bank, and then he wanted to know what I did on a typical day. He asked me if we used Spring Boot or Quarkus, and whether the team worked from home. Then he asked me where the cafeteria was and what time people usually had lunch. He also wanted to know if the manager was strict and who he had to talk to about his laptop. In the end, he asked me if I could help him with his first task, and of course I said I would.", tags: ['asked me how long', 'wanted to know', 'asked me if', 'whether', 'asked me where', 'what time', 'who', 'if I could'] },
          { t: "You'll never believe what happened", task: 'Cuenta una anécdota divertida o extraña (real o inventada) como se la contarías a un amigo: What happened was…, She was like…, I was like…, The strange thing was…. Desvíate un momento y retoma el hilo con Where was I? Oh yeah… o As I was saying…', model: "You'll never believe what happened at the empanada stand on Sunday. What happened was, a customer ordered twenty empanadas for a birthday party and asked me to deliver them at six. I was like, 'No problem.' So at five thirty I get on the motorcycle – oh, by the way, the motorcycle has a new mirror now, I finally fixed it – where was I? Oh yeah, I arrived at the address and it was a dentist's office. The receptionist was like, 'There's no party here.' The strange thing was, the phone number was correct. Turns out, the customer had sent me her office geo-tag instead of her home address. In the end, the dentist bought ten empanadas and the customer picked up the other ten. Everybody was happy!", tags: ["you'll never believe", 'what happened was', 'i was like', 'was like', 'where was i', 'the strange thing was', 'turns out', 'in the end'] },
        ] },
        { label: 'Pronunciación', type: 'stress', eyebrow: 'Pronunciación · sílaba tónica, entonación y comillas irónicas', title: 'conGRAtulate / perSUADE y "You\'ll NEVER believe…"', intro: 'Primero el vocabulario: la sílaba fuerte va en MAYÚSCULAS. Después, las frases para contar historias: la entonación sube en la palabra clave (<i>NEVER, OUT, LIKE</i>) para crear suspenso. Por último, las comillas irónicas: la palabra entre comillas se dice más lenta y con un tono más alto, como si levantaras las cejas. Escucha y repite.',
          pairs: [['conGRAtulate (4 sílabas, fuerza en GRA)', 'congratulate'], ['CRIticize', 'criticize'], ['perSUADE (fuerza al final)', 'persuade'], ['apPArently', 'apparently'], ['GOssip', 'gossip'], ['MENtion · exPLAIN · inFORM · resPOND', 'mention, explain, inform, respond'], ['HASHtag · NEWSfeed · TIMEline (sustantivos compuestos: fuerza en la primera parte)', 'hashtag, newsfeed, timeline'], ['LIFEcaster · LURker · PODcaster', 'lifecaster, lurker, podcaster'], ['TRENding TOpic · STAtus UPdate', 'trending topic, status update'], ["You'll NEVER believe what happened!", "You'll never believe what happened!"], ['Well, turns OUT, he was at home.', 'Well, turns out, he was at home.'], ["What HAPpened was… (pausa, suspenso)", 'What happened was, the phone was in the car the whole time.'], ['He was LIKE, "Of course!"', 'He was like, "Of course!"'], ['In the END, they found it.', 'In the end, they found it.'], ['As I was SAYing… (retomas el hilo)', 'As I was saying, the wedding was beautiful.'], ['Where was I? Oh YEAH…', 'Where was I? Oh yeah, the wedding.'], ['Comillas irónicas: he "accidentally" overslept', 'Someone told me that he "accidentally" overslept.'], ['Comillas irónicas: she was "busy"', 'She said she was "busy" all weekend.'], ['Frase completa', "She asked me what I did for a living, and I told her that I had been a developer for ten years."]] },
      ] },

      /* ================= READING ================= */
      { id: 'read', label: 'Reading', activities: [
        { label: 'Lectura', type: 'reading', eyebrow: 'Reading for main ideas · inferring meaning', title: 'Lurkers, lifecasters and the bait in between', intro: 'Lee una vez para la idea general y otra fijándote en el estilo indirecto (<i>she told me that…, he explained that…, I asked him if…</i>). Las palabras en negrita se preguntan después: intenta deducirlas por el contexto.',
          paragraphs: [
            "Last month I asked twenty friends a simple question: how much do you actually post? The answers were surprising. Fourteen of them admitted that they were <b>lurkers</b>: they told me that they opened their newsfeed several times a day, read everything, and almost never commented or shared. Only two described themselves as lifecasters. One of them, Carla, explained that she had posted a status update about every meal she had eaten in the last year. \"If I don't post it,\" she said, \"it feels like it didn't happen.\"",
            "Between those two groups there is a third character: the headline. A researcher I contacted, Dr. Elena Ruiz, told me that around a third of the news stories that people shared in her study were never actually opened. People read the title, felt something, and clicked \"share\". That is exactly what clickbait is designed for: a <b>misleading</b> title that promises a shock (\"You won't believe what this doctor said\") and delivers almost nothing. Dr. Ruiz mentioned that the most shared stories were not the most important ones, but the ones that made people angry or curious.",
            "I asked her if lurkers were part of the problem. She said they weren't; in fact, she explained that silent readers were often more careful, because they had no <b>incentive</b> to react quickly. The people who shared the most, she added, were those who wanted their timeline to look active and informed. In other words, the pressure to be seen made them careless.",
            "So what did I learn? Carla asked me if I was going to criticize her in this article, and I promised I wouldn't. Posting what you eat hurts nobody. The real danger is <b>amplifying</b> a story you haven't read. Dr. Ruiz gave me one rule that I now repeat to everyone: before you tag a friend, add a hashtag or hit \"share\", open the link. If the article doesn't say what the title promised, you've just caught your first clickbait.",
          ],
          main: [
            { q: 'Most of the people the writer asked read a lot but rarely post.', opts: ['1', '2', '3', '4'], a: '1', why: 'Párrafo 1: <i>Fourteen of them admitted that they were lurkers… almost never commented or shared</i>.' },
            { q: 'Many people share news stories without opening them.', opts: ['1', '2', '3', '4'], a: '2', why: 'Párrafo 2: <i>around a third of the news stories that people shared… were never actually opened</i>.' },
            { q: 'Silent readers tend to be more careful than frequent sharers.', opts: ['1', '2', '3', '4'], a: '3', why: 'Párrafo 3: <i>silent readers were often more careful… The people who shared the most… were careless</i>.' },
            { q: 'The writer gives a simple rule to avoid spreading clickbait.', opts: ['1', '2', '3', '4'], a: '4', why: 'Párrafo 4: <i>before you tag a friend, add a hashtag or hit "share", open the link</i>.' },
          ],
          infer: [
            { q: '<b>lurkers</b> (paragraph 1)', opts: ['people who read posts but hardly ever take part', 'people who post about everything they do', 'people who write news headlines'], a: 'people who read posts but hardly ever take part', why: 'El texto lo explica justo después: <i>read everything, and almost never commented or shared</i>. Vocabulario de la unidad.' },
            { q: '<b>misleading</b> (paragraph 2)', opts: ['giving a false idea of what something is', 'very long and detailed', 'written by a doctor'], a: 'giving a false idea of what something is', why: 'Un título que <i>promises a shock and delivers almost nothing</i>: engaña sobre el contenido.' },
            { q: '<b>incentive</b> (paragraph 3)', opts: ['a reason that encourages you to do something', 'a kind of social media account', 'a mistake you make when you read fast'], a: 'a reason that encourages you to do something', why: 'Los lurkers no tienen <i>incentivo</i> para reaccionar rápido: nadie espera nada de ellos.' },
            { q: '<b>amplifying</b> (paragraph 4)', opts: ['making something reach more people', 'reading something very carefully', 'deleting something from your timeline'], a: 'making something reach more people', why: 'Compartir una historia que no has leído la <i>amplifica</i>: llega a más gente. Es el peligro real del clickbait.' },
          ],
          think: '¿Eres lurker, lifecaster o algo intermedio? Piensa en la última noticia que compartiste: ¿la abriste antes? Escribe tres frases en estilo indirecto sobre lo que te han dicho tus amigos o tu familia de tus redes: <i>My wife told me that I…</i>, <i>A friend once asked me why I…</i>, <i>My mom said that she…</i>' },
      ] },

      /* ================= WRITING ================= */
      { id: 'write', label: 'Writing', activities: [
        { label: 'Cómo recontar', type: 'notes', eyebrow: 'Writing skill · recounting a conversation or a story', title: 'Dos textos de la unidad: el recuento y la publicación', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>A · Recuento de una conversación (recount)</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Gancho:</b> You'll never believe what… / Guess who I ran into yesterday. / I heard that…</li><li><b>Contexto en pasado:</b> I caught up with Renzo on Friday. / What happened was, …</li><li><b>Lo que dijeron, en estilo indirecto:</b> He told me that he <b>had changed</b> jobs. / She said she <b>was working</b> from home. / He explained that the app <b>didn't work</b>.</li><li><b>Lo que preguntaron:</b> He asked me if I <b>was</b> happy at the bank. / She wanted to know what I <b>did</b> on a typical day.</li><li><b>Instrucciones / consejos:</b> He persuaded me <b>to send</b> my CV. / She told me <b>not to mention</b> it.</li><li><b>Giro y cierre:</b> Well, turns out, … / The funny thing was, … / In the end, …</li></ul></div>
          <div><h3>B · Publicación en redes (post)</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Status update corto y concreto:</b> Just finished our first catering order: 200 empanadas for a wedding!</li><li><b>Etiqueta a las personas:</b> Thanks to <b>@Rosa</b> and <b>@Diego</b> for the help. (<i>I tagged them</i>)</li><li><b>Hashtag del tema:</b> <b>#LaConsentidaPE #empanadas #Lima</b></li><li><b>Geoetiqueta:</b> 📍 Miraflores, Lima</li><li><b>Invita a responder:</b> Comment below if you want the recipe! / Reply to this post with your favorite filling.</li><li><b>Nada de clickbait:</b> el título debe decir lo que de verdad hay dentro.</li></ul></div>
          <div class="hint small"><b>Ojo:</b> <s>She said me</s> → <b>She told me</b> / <b>She said</b> · <s>He asked me where did I live</s> → <b>where I lived</b> · <s>explain me</s> → <b>explain to me</b> · <s>reply her</s> → <b>reply to her</b> · <s>congratulate for</s> → <b>congratulate on</b> · <s>contact with me</s> → <b>contact me</b>. En un recuento escrito, evita las comillas: todo va en estilo indirecto.</div></div>` },
        { label: 'Corrige las frases', type: 'fix', eyebrow: 'Error correction · recuentos y publicaciones', title: 'Reescribe la frase corrigiendo el error', intro: 'Frases sacadas de recuentos y publicaciones típicas de hispanohablantes. Un error por frase (a veces dos).', items: [
          { bad: 'My colleague said me that the server was down.', good: 'My colleague told me that the server was down.', why: '<b>say</b> sin persona, <b>tell</b> con persona: <i>told me</i>.' },
          { bad: 'She asked me what do I do for a living.', good: 'She asked me what I did for a living.', why: 'Sin <i>do</i> auxiliar; "hacer" pasa a <b>did</b>; orden sujeto + verbo. Frase del curso.' },
          { bad: 'He told me that he will send the report tomorrow, but he never did.', good: 'He told me that he would send the report the next day, but he never did.', why: 'La promesa ya pasó: <i>will</i> → <b>would</b>, <i>tomorrow</i> → <b>the next day</b>.' },
          { bad: 'The client asked if we could to finish the app in March.', good: 'The client asked if we could finish the app in March.', why: 'Después de <b>could</b>, verbo base sin <i>to</i>.' },
          { bad: 'I posted a status update and I tagged to my sister in the photo.', good: 'I posted a status update and I tagged my sister in the photo.', why: '<b>tag someone</b> (sin <i>to</i>) <b>in</b> a photo.' },
          { bad: 'Apparently, she has told him that she was moving to Chile.', good: 'Apparently, she had told him that she was moving to Chile.', why: 'En una narración en pasado, lo anterior va en <b>past perfect</b>: <i>had told</i>.' },
          { bad: 'My boss informed that the project was cancelled.', good: 'My boss informed us that the project was cancelled.', why: '<b>inform</b> exige persona: <i>informed us that</i>.' },
          { bad: 'Carla asked me why was I so quiet on social media.', good: 'Carla asked me why I was so quiet on social media.', why: 'Orden de afirmación: <i>why <b>I was</b></i>, no <s>was I</s>.' },
          { bad: 'He persuaded me that I buy the premium plan.', good: 'He persuaded me to buy the premium plan.', why: '<b>persuade + persona + TO + verbo</b>, no <i>that</i>.' },
          { bad: 'Nobody responded my message, so I called her.', good: 'Nobody responded to my message, so I called her.', why: '<b>respond TO</b> something.' },
          { bad: 'She mentioned me that the meme was a trending topic.', good: 'She mentioned that the meme was a trending topic.', why: '<b>mention</b> no lleva persona como objeto: <i>mentioned that…</i> (o <i>mentioned <b>to me</b> that…</i>).' },
          { bad: 'I asked him had he seen the new hashtag.', good: 'I asked him if he had seen the new hashtag.', why: 'Pregunta de sí/no → <b>if</b> + sujeto + verbo. Sin inversión.' },
        ] },
        { label: 'Escribe tu recuento', type: 'comment', eyebrow: 'Writing task · recount', title: 'Cuenta una conversación en estilo indirecto', intro: 'Piensa en una conversación real de esta semana (una reunión, una llamada con un cliente, un café con un amigo). Cuéntala en 90-130 palabras: quién, cuándo, qué dijo, qué te preguntó, qué te pidió y cómo terminó. Todo en estilo indirecto, sin comillas. La checklist se marca sola al analizar el texto.', placeholder: "You'll never believe who I ran into on Friday. I caught up with … and she told me that she had … She asked me if I … In the end, …", min: 90, max: 130, need: 5, checks: [
          { label: 'Uso un verbo introductor en pasado (<i>said / told me / explained / mentioned / informed us / commented</i>)', re: /\b(said|told (me|him|her|us|them|my|the|our|everyone|everybody)|explained|mentioned|informed (me|him|her|us|them|the|my|everyone|everybody)|commented|reported|admitted|added)\b/ },
          { label: 'Hago el cambio de tiempo en una afirmación (<i>was / were / had + participio / would / could</i>)', re: /\b(that |told \w+ |said |explained |mentioned )(he|she|they|it|we|i|you|the \w+|his \w+|her \w+|my \w+|there)\s+(was|were|had|would|could|might|wasn['’]t|weren['’]t|hadn['’]t|wouldn['’]t|couldn['’]t|didn['’]t)\b/ },
          { label: 'Reporto una pregunta (<i>asked me if / asked me where / wanted to know what…</i>) sin <i>do / does / did</i>', re: /\b(asked( me| him| her| us| them| \w+)?|wanted to know|wondered)\s+(if|whether|what|where|when|why|who|which|how)\b(?! (do|does|did|are|is|was|were|can|could|will|would|have|has|had) (i|you|he|she|we|they|it)\b)/ },
          { label: 'Reporto una instrucción, petición o consejo (<i>told me to / asked me to / persuaded me to / told me not to</i>)', re: /\b(told|asked|persuaded|advised|reminded|convinced|encouraged) (me|him|her|us|them|my \w+|the \w+|\w+) (not )?to \w+/ },
          { label: 'Uso una frase para contar historias (<i>You\'ll never believe… / Apparently / turns out / What happened was / The funny thing was / In the end</i>)', re: /\b(you['’]ll never (believe|guess)|guess (who|what)|apparently|turns out|what happened was|the (funny|strange|weird|best|worst) thing (was|is)|in the end|someone told me|i heard that|was like)\b/ },
          { label: 'Uso al menos dos palabras de la unidad (<i>catch up with, mention, gossip, persuade, reply to, keep in touch, newsfeed, tag, hashtag, meme, status update…</i>)', re: /\b(catch(ing)? up with|caught up with|comment(ed|s)? on|congratulat(e|ed|ing)|contact(ed)?|criticiz(e|ed|es)|gossip(ed|ing|s)?|inform(ed)? \w+ of|keep in touch|kept in touch|mention(ed|s)?|persuad(e|ed)|repl(y|ied) to|respond(ed)? to|report(ed|ing)? on|newsfeed|timeline|hashtag|meme|status update|tag(ged)?|profile|trending topic|clickbait|lurker|lifecaster|podcaster|geo-tag)\b[\s\S]*\b(catch(ing)? up with|caught up with|comment(ed|s)? on|congratulat(e|ed|ing)|contact(ed)?|criticiz(e|ed|es)|gossip(ed|ing|s)?|inform(ed)? \w+ of|keep in touch|kept in touch|mention(ed|s)?|persuad(e|ed)|repl(y|ied) to|respond(ed)? to|report(ed|ing)? on|newsfeed|timeline|hashtag|meme|status update|tag(ged)?|profile|trending topic|clickbait|lurker|lifecaster|podcaster|geo-tag)\b/ },
          { label: 'No uso comillas: todo va en estilo indirecto', re: /^(?![\s\S]*["“”])[\s\S]+$/ },
        ] },
        { label: 'Escribe tu publicación', type: 'comment', eyebrow: 'Writing task · social media post', title: 'Publica una actualización de estado', intro: 'Escribe una publicación para La Consentida PE o para tu perfil personal (40-80 palabras): qué pasó, a quién etiquetas, hashtag, geoetiqueta y una invitación a responder. Sin clickbait: el texto debe decir lo que de verdad pasó. La checklist se marca sola.', placeholder: 'Just finished … Thanks to @… for … 📍 Lima #… Comment below if …', min: 40, max: 80, need: 4, checks: [
          { label: 'Cuento qué pasó con un verbo en pasado o present perfect (<i>just finished, we delivered, has been…</i>)', re: /\b(just (finished|delivered|posted|arrived|launched|opened|sold)|we (delivered|made|sold|cooked|finished|opened|launched|had)|i (delivered|made|sold|cooked|finished|posted|met|caught up)|has been|have been|was|were)\b/ },
          { label: 'Etiqueto a alguien (<i>@nombre</i> o <i>I tagged…</i>)', re: /(@\w+|\btag(ged)? (my|our|the|him|her|them|you|everyone|everybody|\w+ and))/ },
          { label: 'Uso al menos un hashtag (<i>#…</i>)', re: /#\w{2,}/ },
          { label: 'Añado una geoetiqueta o el lugar (<i>📍 Lima / in Miraflores / at …</i>)', re: /(📍|\bgeo-?tag|\b(in|at|from) (lima|miraflores|surco|callao|barranco|san isidro|la victoria|san borja|lince|chorrillos|cusco|arequipa|trujillo|peru|chile|santiago|the (office|market|shop|stand|kitchen|restaurant|cafe|café|fair|park))\b)/ },
          { label: 'Invito a responder o a comentar (<i>comment below, reply to this post, let me know, tell us</i>)', re: /\b(comment below|reply to this|let (me|us) know|tell (me|us)|what do you think|share (this|it|your)|send (me|us) a message|dm (me|us))\b/ },
          { label: 'Uso una palabra más de la unidad (<i>status update, newsfeed, timeline, profile, trending topic, meme, geo-tag, podcaster, catch up with, keep in touch…</i>)', re: /\b(status update|newsfeed|timeline|profile|trending topic|meme|geo-?tag|podcast(er)?|lurkers?|lifecasters?|clickbait|catch up with|keep in touch|congratulat(e|ions)|mention(ed)?|respond(ed)? to|repl(y|ied) to)\b/ },
        ] },
      ] },

      /* ================= SOCIAL ENGLISH ================= */
      { id: 'social', label: 'Social English', activities: [
        { label: 'Frases', type: 'notes', eyebrow: 'Functional language · Lesson 3', title: 'Recontar conversaciones, noticias e historias', html: `<div class="grid2" style="margin-top:12px">
          <div><h3>Empezar y enganchar</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>You'll never believe / guess what</b> happened!</li><li><b>I heard that</b> David missed the wedding.</li><li><b>Someone told me that</b> he overslept.</li><li><b>Apparently,</b> he had all the info on his phone.</li><li><b>What happened was,</b> he lost his phone.</li></ul></div>
          <div><h3>Desarrollar y cerrar</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>He was like,</b> "Of course!" (informal = <i>he said</i>)</li><li><b>Well, turns out,</b> he was at home all day.</li><li><b>The funny / strange thing was,</b> nobody called him.</li><li><b>In the end,</b> they found the phone in the car.</li></ul></div>
          <div><h3>Retomar el hilo (getting back on track)</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>As I was saying,</b> the wedding was beautiful.</li><li><b>Where was I? Oh yeah,</b> the phone.</li><li><b>What was I saying?</b></li><li><b>I lost my train of thought!</b></li></ul></div>
          <div><h3>Insider English</h3><ul class="small" style="padding-left:18px;margin:6px 0"><li><b>Comillas irónicas:</b> con la entonación (o con comillas al escribir) dices que <b>no te lo crees</b>: <i>Someone told me that he "accidentally" overslept.</i> = seguro que no fue un accidente.</li><li><b>I'm like / he was like / she was like:</b> forma informal de reportar lo que alguien dijo (o pensó, o su reacción): <i>She was wearing a very nice suit, and I was like, "You must have a job interview!"</i></li></ul></div>
          <div class="hint small"><b>Estructura típica de un chisme en inglés:</b> gancho (<i>You'll never believe what…</i>) → fuente (<i>Apparently… / Someone told me that…</i>) → qué pasó (<i>What happened was,…</i>) → reacciones (<i>He was like,…</i>) → giro (<i>Well, turns out,…</i>) → comentario (<i>The funny thing was,…</i>) → cierre (<i>In the end,…</i>). Si te interrumpen o te desvías: <i>Where was I? Oh yeah,…</i> / <i>As I was saying,…</i>. Ojo: <i>Apparently</i> va al principio y con coma; <i>turns out</i> suele ir sin sujeto en el habla (<i>Well, turns out, …</i> = <i>It turns out that…</i>).</div></div>` },
        { label: 'Ordena el diálogo', type: 'order', eyebrow: 'Ordena el diálogo', title: 'Toca las líneas en el orden correcto', intro: 'Tres conversaciones informales: un chisme, una noticia y una historia con interrupción. Fíjate en el orden natural: gancho → qué pasó → reacción → giro → cierre.', dialogs: [
          ["Carla: You'll never believe what happened to Andrés at the airport.", 'Beto: What? Tell me!', 'Carla: What happened was, he arrived two hours early, sat down to watch a series and missed his flight.', 'Beto: No way! How do you miss a flight when you are already there?', 'Carla: Apparently, his headphones were too good. He was like, "I never heard the announcements."', 'Beto: And then?', 'Carla: Well, turns out, the next flight was full, so he slept at the airport.', 'Beto: Poor guy. The funny thing is, he is the one who always criticizes us for being late.'],
          ['Rosa: Did you see the news about the new metro line?', "Pablo: No, I'm a lurker on social media, I never check my newsfeed. What happened?", 'Rosa: I heard that the first stations are going to open in March.', "Pablo: That's not what I heard. Someone told me that it had been delayed again.", 'Rosa: Well, the mayor said on TV that they would open on time. It was a trending topic all morning.', 'Pablo: Hmm. The "official" date has changed three times already.', 'Rosa: Ha! I know what you mean. In the end, we will believe it when we see it.'],
          ['Diego: So I was telling you about the client meeting. The manager asked me how long the migration would take…', 'Ana: Wait, is that the same manager who called you at midnight last week?', 'Diego: Yes! Same one. She called because her laptop was… anyway, what was I saying?', 'Ana: The migration. She asked you how long it would take.', 'Diego: Oh yeah. As I was saying, I told her it would take three months, and she was like, "You have six weeks."', 'Ana: Six weeks? What did you say?', 'Diego: I explained that the tests alone needed a month. Where was I? Oh yeah, in the end she gave us ten weeks.', 'Ana: Not bad. I lost my train of thought too, by the way. What were we going to have for lunch?'],
        ] },
        { label: 'Retoma el hilo', type: 'soft', eyebrow: 'Getting back on track · escritura', title: 'Te interrumpieron o te desviaste: vuelve a la historia', explain: 'Lee la situación y escribe la frase con la que retomarías el hilo. Usa una fórmula de la unidad: <b>As I was saying,…</b> · <b>Where was I? Oh yeah,…</b> · <b>What was I saying?</b> · <b>I lost my train of thought!</b> Y continúa con la historia (al menos unas palabras más).', missing: 'Falta una fórmula para retomar el hilo: <i>As I was saying… · Where was I? Oh yeah… · What was I saying? · I lost my train of thought!</i>', pattern: /\b(as i was saying|where was i|what was i saying|i lost my train of thought|anyway,? (as i was saying|where was i|back to))\b/, items: [
          { h: 'Estabas contando la boda de Marco y tu amigo te interrumpió para preguntar por la comida. Vuelves a la historia de David.', a: 'Anyway, as I was saying, David missed the whole ceremony.' },
          { h: 'Te desviaste hablando de tu moto nueva y no recuerdas por dónde ibas. Ibas por la entrega de empanadas.', a: 'Where was I? Oh yeah, the delivery. So I arrived at the address and it was a dentist\'s office.' },
          { h: 'Te quedaste en blanco en medio de la historia del cliente. Lo admites con humor y sigues.', a: 'Sorry, I lost my train of thought! Oh yeah, the manager asked me how long the migration would take.' },
          { h: 'Sonó tu teléfono mientras contabas lo del meme. Cuelgas y preguntas por dónde ibas.', a: 'What was I saying? Oh yeah, the meme became a trending topic in two hours.' },
          { h: 'Tu colega te interrumpió con una pregunta sobre otro proyecto. Respondes rápido y vuelves al tema de la reunión.', a: 'As I was saying, in the meeting she asked me if we could start in November.' },
          { h: 'Estabas recontando una noticia y empezaste a hablar del clima. Vuelves a la noticia del metro.', a: 'Anyway, where was I? Oh yeah, the metro line. Apparently, it opens in March.' },
        ] },
        { label: 'Respuesta rápida', type: 'mcq', eyebrow: 'Respuesta rápida', title: '¿Qué dices? ¿Qué significa?', items: [
          { q: 'Vas a contar algo sorprendente que pasó en la oficina. ¿Cómo empiezas?', opts: ["You'll never believe what happened at the office!", 'As I was saying, the office…', 'I lost my train of thought!'], a: "You'll never believe what happened at the office!", why: '<b>You\'ll never believe / guess what…</b> es el gancho para empezar.' },
          { q: 'No viste el hecho; te lo contaron. ¿Qué dices para marcar que es de oídas?', opts: ['Apparently, he lost his phone.', 'In the end, he lost his phone.', 'What was I saying? He lost his phone.'], a: 'Apparently, he lost his phone.', why: '<b>Apparently</b> = según dicen / parece ser. También <i>I heard that… / Someone told me that…</i>' },
          { q: 'Quieres introducir el giro de la historia: la verdad era otra.', opts: ['Well, turns out, he was at home the whole time.', 'As I was saying, he was at home.', 'Someone told me that he was at home.'], a: 'Well, turns out, he was at home the whole time.', why: '<b>Well, turns out,…</b> introduce lo que resultó ser verdad.' },
          { q: 'Te interrumpieron y quieres seguir donde lo dejaste.', opts: ['As I was saying, the wedding was beautiful.', "You'll never believe what happened.", 'The funny thing was, the wedding was beautiful.'], a: 'As I was saying, the wedding was beautiful.', why: '<b>As I was saying</b> = como iba diciendo.' },
          { q: 'Te quedaste en blanco en medio de la historia.', opts: ['I lost my train of thought!', 'Turns out, I forgot.', 'In the end, I forgot.'], a: 'I lost my train of thought!', why: '<b>lose your train of thought</b> = perder el hilo de lo que estabas diciendo.' },
          { q: 'Quieres reportar de forma muy informal lo que dijo tu amigo ("¡Claro!").', opts: ['He was like, "Of course!"', 'He informed me of course.', 'He reported that of course.'], a: 'He was like, "Of course!"', why: 'Insider English: <b>he was like</b> = <i>he said</i>, informal. <i>Inform / report</i> son formales.' },
          { q: 'Alguien dice: "Someone told me that he “accidentally” overslept." ¿Qué quiere decir con las comillas?', opts: ["He doesn't believe it was an accident.", 'He is sure it was an accident.', 'He is quoting a newspaper.'], a: "He doesn't believe it was an accident.", why: 'Comillas irónicas (y la entonación al hablar) = <b>no me lo creo</b>.' },
          { q: 'Tu colega dice: "She said she was “busy” all weekend." ¿Qué piensa tu colega?', opts: ["That she probably wasn't really busy.", 'That she worked all weekend.', 'That she was in the hospital.'], a: "That she probably wasn't really busy.", why: 'La palabra entre comillas es la que <b>no se cree</b>.' },
          { q: 'Terminas la historia contando cómo acabó todo.', opts: ['In the end, they found the phone in the car.', 'What happened was, they found the phone.', 'Apparently, they found the phone.'], a: 'In the end, they found the phone in the car.', why: '<b>In the end</b> = al final (resultado). Ojo: <i>at the end of</i> es el final físico de algo (<i>at the end of the street</i>).' },
          { q: 'Quieres destacar lo curioso de la historia.', opts: ['The funny thing was, nobody had noticed.', 'As I was saying, nobody had noticed.', 'Where was I? Nobody had noticed.'], a: 'The funny thing was, nobody had noticed.', why: '<b>The funny / strange thing was,…</b> destaca el detalle curioso.' },
          { q: 'Vas a explicar paso a paso lo que ocurrió.', opts: ['What happened was, I sent the email to the wrong client.', 'I lost my train of thought! I sent the email.', 'The funny thing was, I sent the email.'], a: 'What happened was, I sent the email to the wrong client.', why: '<b>What happened was,…</b> introduce la explicación de los hechos.' },
          { q: 'Te preguntan "What was I saying?" después de una interrupción. ¿Qué respondes?', opts: ['You were telling me about the client meeting.', "You'll never believe what happened.", 'Apparently, you were saying.'], a: 'You were telling me about the client meeting.', why: 'Ayudas a retomar el hilo recordando el tema: <i>You were telling me about…</i>' },
        ] },
      ] },
    ],
  };
})();
